// VerificationResult is `verification-result` (shared/schemas/signing-vectors.cddl): a choice of VerificationRefusal, VerificationResultValid and VerificationResultInvalid, each held by value (a pointer to one is no alternative).
type VerificationResult interface {
	isVerificationResult()
}

// VerificationResultValid is the text "valid", an alternative of VerificationResult.
type VerificationResultValid struct{}

// VerificationResultInvalid is the text "invalid", an alternative of VerificationResult.
type VerificationResultInvalid struct{}

func (VerificationRefusal) isVerificationResult() {}

func (VerificationResultValid) isVerificationResult() {}

func (VerificationResultInvalid) isVerificationResult() {}

// EncodeVerificationResult is the canonical value of x, encoded at at: a nil x, or one of a type that is not an alternative, is
// a TypeMismatch.
func EncodeVerificationResult(x VerificationResult, at core.Encoding) (core.Value, error) {
	switch alt := x.(type) {
	case VerificationRefusal:
		return EncodeVerificationRefusal(alt, at)
	case VerificationResultValid:
		return core.EncodeLiteralText("valid", at)
	case VerificationResultInvalid:
		return core.EncodeLiteralText("invalid", at)
	}
	return core.Value{}, core.NoAlternative("VerificationResult")
}

// DecodeVerificationResult is the alternative of VerificationResult that v is: a record by its keys, a text by itself.
func DecodeVerificationResult(v core.Value) (VerificationResult, error) {
	i, err := core.SelectAlternative(v, []core.Keys{{Required: []string{"kind", "part"}, Allowed: []string{"kind", "part"}}}, []string{"valid", "invalid"})
	if err != nil {
		return nil, err
	}
	switch i {
	case 0:
		rec, err := DecodeVerificationRefusal(v)
		if err != nil {
			return nil, err
		}
		return rec, nil
	case 1:
		return VerificationResultValid{}, nil
	case 2:
		return VerificationResultInvalid{}, nil
	}
	return nil, core.UnknownAlternative(i)
}
